function validate([words, pref]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 100) return 'words needs 1 to 100 strings.';
  if (typeof pref !== 'string' || pref.length < 1 || pref.length > 100) return 'pref has 1 to 100 letters.';
  if (!/^[a-z]+$/.test(pref)) return 'pref uses only lowercase letters.';
  for (const word of words) {
    if (typeof word !== 'string' || word.length < 1 || word.length > 100) return 'Each word has 1 to 100 letters.';
    if (!/^[a-z]+$/.test(word)) return 'Words use only lowercase letters.';
  }
  return null;
}

