function prefixCount(words, pref) {
  let count = 0;
  for (const word of words) {
    if (word.length < pref.length) {
      continue;
    }
    let matches = true;
    for (let i = 0; i < pref.length; i++) {
      if (word[i] !== pref[i]) {
        matches = false;
        break;
      }
    }
    if (matches) {
      count++;
    }
  }
  return count;
}

