function generate(rand, size) {
  const large = size === 'large';
  const letters = 'abcdefghijklmnopqrstuvwxyz'.slice(0, 2 + Math.floor(rand() * (large ? 4 : 2)));
  const text = (len) => Array.from({ length: len }, () => letters[Math.floor(rand() * letters.length)]).join('');
  const prefLen = 1 + Math.floor(rand() * (large ? 40 : 3));
  const pref = text(prefLen);
  const count = large ? 100 : 1 + Math.floor(rand() * 6);
  const maxLen = large ? 100 : 5;
  const words = Array.from({ length: count }, () => {
    const roll = rand();
    if (roll < 0.4 && prefLen <= maxLen) {
      // Starts with pref, then some extra letters.
      return pref + text(Math.floor(rand() * (maxLen - prefLen + 1)));
    }
    if (roll < 0.6 && prefLen > 1) {
      // A near miss: pref with one letter changed or cut short.
      const cut = Math.floor(rand() * prefLen);
      return rand() < 0.5 ? pref.slice(0, cut) || letters[0] : pref.slice(0, cut) + (pref[cut] === 'a' ? 'b' : 'a') + text(Math.floor(rand() * 3));
    }
    return text(1 + Math.floor(rand() * maxLen));
  });
  return [words, pref];
}
